def _qk_topk_prefill(
    q: torch.Tensor,
    k: torch.Tensor,
    w: torch.Tensor,
    topk: int,
    cu_seq_len_k_start: torch.Tensor,
    cu_seq_len_k_end: torch.Tensor,
    chunk_size: int,
    max_seqlen: Optional[int] = None,
    return_global_indices: bool = False,
    topk_impl: str = "torch",
    k_scales: torch.Tensor | None = None,
    sm_scale: Optional[float] = None,
    is_indexer_topk: bool = True,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Compute packed prefill logits and select top-k in query chunks.

    Causality and other per-query windows are already encoded by
    ``cu_seq_len_k_start`` and ``cu_seq_len_k_end``. Fused-style inputs with
    shape ``[1, S, H, D]`` / ``[1, S, H]`` return fused-style outputs with shape
    ``[1, S, topk]``. Packed local inputs with shape ``[S, H, D]`` / ``[S, H]``
    are also accepted for the internal worker path.

    Returns:
        ``(values, indices)`` with shape ``[1, S_q, topk]`` for fused-style
        inputs, or ``[S_q, topk]`` for packed local inputs. Values are float32
        and indices are int32. Indices are relative to each row's KV start
        unless ``return_global_indices`` is true. Missing entries are padded
        with ``-inf`` and index ``-1``. The ``indexer`` implementation returns
        indices in its native unsorted order.
        Pass ``k_scales`` when ``k`` is fp8. When ``is_indexer_topk`` is false,
        ``w`` is interpreted as QK softmax LSE.
    """

    is_fused_shape = q.ndim == 4
    if is_fused_shape:
        if k.ndim != 4 or w.ndim != 3:
            raise ValueError("fused-style q/k must be 4D and w must be 3D")
        if q.shape[0] != 1 or k.shape[0] != 1 or w.shape[0] != 1:
            raise ValueError("indexer_qk_topk_prefill currently supports B == 1")
        q_work = q[0]
        k_work = k[0]
        w_work = w[0]
    else:
        if q.ndim != 3 or k.ndim != 3 or w.ndim != 2:
            raise ValueError("q and k must be 3D and w must be 2D")
        q_work = q
        k_work = k
        w_work = w

    num_query = q_work.shape[0]
    if w_work.shape[0] != num_query:
        raise ValueError("q and w must have the same number of query rows")
    if cu_seq_len_k_start.shape != (num_query,):
        raise ValueError(
            f"cu_seq_len_k_start must have shape ({num_query},), "
            f"got {tuple(cu_seq_len_k_start.shape)}"
        )
    if cu_seq_len_k_end.shape != (num_query,):
        raise ValueError(
            f"cu_seq_len_k_end must have shape ({num_query},), "
            f"got {tuple(cu_seq_len_k_end.shape)}"
        )
    if chunk_size <= 0:
        raise ValueError(f"chunk_size must be positive, got {chunk_size}")
    if topk <= 0:
        raise ValueError(f"topk must be positive, got {topk}")
    if topk_impl not in {"torch", "indexer"}:
        raise ValueError(
            f"topk_impl must be 'torch' or 'indexer', got {topk_impl!r}"
        )
    if not is_indexer_topk and k_scales is not None:
        raise ValueError("full qk topk does not support fp8 k_scales")
    if max_seqlen is None:
        max_seqlen = k_work.shape[0]
    if max_seqlen <= 0:
        raise ValueError(f"max_seqlen must be positive, got {max_seqlen}")
    if topk > max_seqlen:
        raise ValueError(
            f"topk ({topk}) must not exceed max_seqlen ({max_seqlen})"
        )

    topk_values = torch.empty(
        (num_query, topk), device=q_work.device, dtype=torch.float32
    )
    topk_indices = torch.empty(
        (num_query, topk), device=q_work.device, dtype=torch.int32
    )
    logits_workspace = torch.empty(
        (min(chunk_size, num_query), max_seqlen),
        device=q_work.device,
        dtype=torch.float32,
    )
    indexer_row_starts = torch.zeros(
        min(chunk_size, num_query), device=q_work.device, dtype=torch.int32
    )

    for query_start in range(0, num_query, chunk_size):
        query_end = min(query_start + chunk_size, num_query)
        chunk_k_start = cu_seq_len_k_start[query_start:query_end]
        chunk_k_end = cu_seq_len_k_end[query_start:query_end]
        chunk_logits = logits_workspace[: query_end - query_start]
        # torch.topk has no per-row valid-length input, so we must pre-fill
        # the unwritten tail with -inf. The indexer kernel takes valid_lengths
        # and only reads [0, valid_len) of each row, so the fill is wasted
        # work on that path (~8% of wall on the 1M shape).
        if topk_impl == "torch":
            chunk_logits.fill_(float("-inf"))
        indexer_logits_prefill_fwd(
            q_work[query_start:query_end],
            k_work,
            w_work[query_start:query_end],
            chunk_k_start,
            chunk_k_end,
            max_seqlen=max_seqlen,
            output=chunk_logits,
            k_scales=k_scales,
            is_compressed_logits=True,
            sm_scale=sm_scale,
            is_indexer_topk=is_indexer_topk,
        )
        valid_lengths = chunk_k_end - chunk_k_start
